<template>
	<view class="stats-container">
		<view class="header">
			<view class="header-title">📊 统计报表</view>
			<view class="header-desc">项目进度、任务完成情况统计</view>
		</view>
		
		<view class="overview-grid">
			<view class="overview-card">
				<view class="overview-icon">📋</view>
				<view class="overview-value">{{ stats.totalProjects }}</view>
				<view class="overview-label">总项目数</view>
			</view>
			<view class="overview-card">
				<view class="overview-icon">✅</view>
				<view class="overview-value">{{ stats.doneProjects }}</view>
				<view class="overview-label">已完成</view>
			</view>
			<view class="overview-card">
				<view class="overview-icon">📝</view>
				<view class="overview-value">{{ stats.totalTasks }}</view>
				<view class="overview-label">总任务数</view>
			</view>
			<view class="overview-card">
				<view class="overview-icon">🎉</view>
				<view class="overview-value">{{ stats.doneTasks }}</view>
				<view class="overview-label">已完成</view>
			</view>
		</view>
		
		<view class="progress-section">
			<view class="section-title">完成率</view>
			<view class="progress-card">
				<view class="progress-item">
					<view class="progress-header">
						<text class="progress-label">项目完成率</text>
						<text class="progress-percent">{{ stats.projectCompletionRate }}%</text>
					</view>
					<view class="progress-bar">
						<view class="progress-fill" :style="{ width: stats.projectCompletionRate + '%' }"></view>
					</view>
				</view>
				<view class="progress-item">
					<view class="progress-header">
						<text class="progress-label">任务完成率</text>
						<text class="progress-percent">{{ stats.taskCompletionRate }}%</text>
					</view>
					<view class="progress-bar">
						<view class="progress-fill" :style="{ width: stats.taskCompletionRate + '%' }"></view>
					</view>
				</view>
			</view>
		</view>
		
		<view class="warning-section">
			<view class="section-title">⚠️ 延期提醒</view>
			<view class="warning-card" v-if="stats.overdueTasks > 0">
				<text class="warning-text">有 {{ stats.overdueTasks }} 个任务已延期，请及时处理</text>
			</view>
			<view class="empty-warning" v-else>
				<text class="empty-icon">✓</text>
				<text class="empty-text">暂无延期任务</text>
			</view>
		</view>
		
		<view class="team-section">
			<view class="section-title">👥 团队工作量</view>
			<view class="team-list">
				<view class="team-item" v-for="member in teamMembers" :key="member.id">
					<view class="member-avatar">{{ member.name.charAt(0) }}</view>
					<view class="member-info">
						<view class="member-name">{{ member.name }}</view>
						<view class="member-role">{{ member.roleName }}</view>
					</view>
					<view class="member-stats">
						<text class="stat-text">{{ member.taskCount }} 个任务</text>
					</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script>
import api from '@/api/index.js'
import { mockUsers } from '@/api/mock.js'

export default {
	data() {
		return {
			stats: {
				totalProjects: 0,
				doneProjects: 0,
				totalTasks: 0,
				doneTasks: 0,
				overdueTasks: 0,
				projectCompletionRate: 0,
				taskCompletionRate: 0
			},
			teamMembers: []
		}
	},
	onLoad() {
		this.loadStats()
		this.loadTeamMembers()
	},
	onShow() {
		this.loadStats()
	},
	methods: {
		async loadStats() {
			try {
				const res = await api.getStatistics()
				if (res.success) {
					this.stats = res.data
				}
			} catch (e) {
				console.error(e)
			}
		},
		
		loadTeamMembers() {
			const roleMap = {
				manager: '店长',
				staff: '店员',
				developer: '研发'
			}
			
			this.teamMembers = mockUsers.map((user, idx) => ({
				...user,
				roleName: roleMap[user.role] || user.role,
				taskCount: Math.floor(Math.random() * 10) + 1
			}))
		}
	}
}
</script>

